gpn(){return"\ub69c\ub837\ud55c AI \ubb38\uccb4 \ud328\ud134\uc774 \uac10\uc9c0\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4"},
po(a){return"PAN 2025 lexical fingerprint leans AI ("+a+u.e},
