gpc(){return"\ud328\ub7ec\ud504\ub808\uc774\uc988 \uac10\uc9c0 \ubaa8\ub378\uc774 \uc124\uce58\ub418\uc9c0 \uc54a\uc544 \uc774\ubc88 \ud22c\ud45c\uc5d0 \ucc38\uc5ec\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4"},
gpC(){return"\ubaa8\ub378\uc774 \uc124\uce58\ub418\uc9c0 \uc54a\uc558\uac70\ub098 \uc0ac\uc6a9 \uc911\uc778 \ubaa8\ub378\uc774 \uc9c0\uc6d0\ub418\uc9c0 \uc54a\uc544 \uc774\ubc88 \ud22c\ud45c\uc5d0 \ucc38\uc5ec\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4"},
gtz(){return"\ud65c\uc131\ud654\ub41c \ubaa8\ub378\uc744 \ucc3e\uc744 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \ubaa8\ub378 \uad00\ub9ac\uc5d0\uc11c \ucd94\ucc9c \ubaa8\ub378\uc744 \ub2e4\uc6b4\ub85c\ub4dc\ud558\uc138\uc694."},
gty(){return"\ub85c\ub4dc\uc5d0 \uc2e4\ud328\ud55c \uc0ac\uc6a9\uc790 \uc9c0\uc815 \ubaa8\ub378\uc744 \uc81c\uac70\ud588\uc2b5\ub2c8\ub2e4. \uc0ac\uc6a9\uc790 \uc9c0\uc815 \ubaa8\ub378\uc740 \uc790\ub3d9\uc73c\ub85c \ub2e4\uc2dc \ub2e4\uc6b4\ub85c\ub4dc\ud560 \uc218 \uc5c6\uc73c\ubbc0\ub85c \ubaa8\ub378\uacfc \ud1a0\ud06c\ub098\uc774\uc800\ub97c \ub2e4\uc2dc \uac00\uc838\uc624\uc138\uc694."},
