tC(a){return"\ubaa8\ub378 \ud30c\uc77c\uc774 \uc190\uc0c1\ub418\uc5c8\uac70\ub098 \ud638\ud658\ub418\uc9c0 \uc54a\uc744 \uc218 \uc788\uc74c\uc744 \uac10\uc9c0\ud558\uc5ec "+a+"\uc744(\ub97c) \uc790\ub3d9\uc73c\ub85c \ub2e4\uc2dc \ub2e4\uc6b4\ub85c\ub4dc\ud588\uc2b5\ub2c8\ub2e4. \ubd84\uc11d\uc744 \ub2e4\uc2dc \uc2e4\ud589\ud558\uc138\uc694."},
tB(a){return"\ub85c\ub4dc\uc5d0 \uc2e4\ud328\ud55c \ubaa8\ub378 \ud30c\uc77c\uc744 \uc81c\uac70\ud588\uc9c0\ub9cc \uc790\ub3d9 \uc7ac\ub2e4\uc6b4\ub85c\ub4dc\uac00 \uc644\ub8cc\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \ub124\ud2b8\uc6cc\ud06c \uc5f0\uacb0\uc744 \ud655\uc778\ud55c \ud6c4 \ubaa8\ub378 \uad00\ub9ac\uc5d0\uc11c "+a+"\uc744(\ub97c) \ub2e4\uc2dc \ub2e4\uc6b4\ub85c\ub4dc\ud558\uc138\uc694."},
gpI(){return"\ud65c\uc131\ud654\ub41c Transformer \ubaa8\ub378\uc744 \ucc3e\uc744 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \ubaa8\ub378 \uad00\ub9ac\uc5d0\uc11c \ub2e4\uc6b4\ub85c\ub4dc\ud558\uac70\ub098 \ud65c\uc131\uc73c\ub85c \uc124\uc815\ud558\uc138\uc694"},
pM(a){return"\uc0ac\uc6a9 \uc911\uc778 \ubaa8\ub378\uc758 tokenizer \uc720\ud615\uc774 \uc9c0\uc6d0\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4\uff08"+a+"\uff09. bert-wordpiece \ub610\ub294 roberta-bpe\ub97c \uc9c0\uc6d0\ud558\ub294 \ubaa8\ub378\ub85c \uc804\ud658\ud558\uc138\uc694"},
gpH(){return"Transformer \ubaa8\ub378 \ub610\ub294 tokenizer \uacbd\ub85c\uac00 \uc5c6\uc2b5\ub2c8\ub2e4. \ubaa8\ub378 \uad00\ub9ac\uc5d0\uc11c \ub2e4\uc2dc \ub2e4\uc6b4\ub85c\ub4dc\ud558\uc138\uc694"},
gpG(){return"Transformer \ubaa8\ub378 \ub610\ub294 tokenizer \ud30c\uc77c\uc774 \uc874\uc7ac\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ubaa8\ub378 \uad00\ub9ac\uc5d0\uc11c \ub2e4\uc2dc \ub2e4\uc6b4\ub85c\ub4dc\ud558\uc138\uc694"},
pJ(a){return"ONNX opset \ubc84\uc804\uc774 \uc9c0\uc6d0\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4\uff08\uc774 \ubaa8\ub378 \ubc84\uc804\uc774 \ub108\ubb34 \ucd5c\uc2e0\uc785\ub2c8\ub2e4. \uc571\uc744 \uc5c5\ub370\uc774\ud2b8\ud558\uc138\uc694\uff09: "+a},
pL(a){return"Tokenizer \ud615\uc2dd\uc774 \uc190\uc0c1\ub418\uc5c8\uc2b5\ub2c8\ub2e4: "+a},
gpK(){return"\ubaa8\ub378 \ub85c\ub4dc \ub610\ub294 \ucd94\ub860\uc5d0 \uc2e4\ud328\ud588\uc73c\uba70 \uc790\ub3d9 \ubcf5\uad6c\ub3c4 \uc644\ub8cc\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \ubaa8\ub378 \uad00\ub9ac\uc5d0\uc11c \ud65c\uc131 Transformer \ubaa8\ub378\uacfc tokenizer\ub97c \ub2e4\uc2dc \ub2e4\uc6b4\ub85c\ub4dc\ud558\uc138\uc694."},
gp9(){return"\ud65c\uc131\ud654\ub41c \uc7ac\uc791\uc131 \uac10\uc9c0 \ubaa8\ub378\uc744 \ucc3e\uc744 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4"},
gp8(){return"\ubaa8\ub378 \ub610\ub294 tokenizer \ud30c\uc77c\uc774 \uc874\uc7ac\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ubaa8\ub378 \uad00\ub9ac\uc5d0\uc11c \ub2e4\uc2dc \ub2e4\uc6b4\ub85c\ub4dc\ud558\uc138\uc694"},
gpa(){return"\ubaa8\ub378 \ub85c\ub4dc \ub610\ub294 \ucd94\ub860\uc5d0 \uc2e4\ud328\ud588\uc73c\uba70 \uc790\ub3d9 \ubcf5\uad6c\ub3c4 \uc644\ub8cc\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \ubaa8\ub378 \uad00\ub9ac\uc5d0\uc11c \uc7ac\uc791\uc131 \uac10\uc9c0 \ubaa8\ub378\uacfc tokenizer\ub97c \ub2e4\uc2dc \ub2e4\uc6b4\ub85c\ub4dc\ud558\uc138\uc694."},
m1(a){return"\uc774 \ubaa8\ub378\uc740 \uc774\ubc88 \ud22c\ud45c\uc5d0 \ucc38\uc5ec\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. "+a},
