gui(){return"\u0418\u0441\u0442\u043e\u0440\u0438\u044f \u043f\u0440\u0430\u0432\u043e\u043a \u044f\u0432\u043d\u043e \u043d\u0435\u043e\u0431\u044b\u0447\u043d\u0430"},
guk(){return"\u0412 \u0438\u0441\u0442\u043e\u0440\u0438\u0438 \u043f\u0440\u0430\u0432\u043e\u043a \u0435\u0441\u0442\u044c \u0441\u0442\u0440\u0430\u043d\u043d\u043e\u0441\u0442\u0438"},
guj(){return"\u0418\u0441\u0442\u043e\u0440\u0438\u044f \u043f\u0440\u0430\u0432\u043e\u043a \u0432\u044b\u0433\u043b\u044f\u0434\u0438\u0442 \u043e\u0431\u044b\u0447\u043d\u043e\u0439"},
gul(){return"\u0418\u0441\u0442\u043e\u0440\u0438\u044f \u043f\u0440\u0430\u0432\u043e\u043a \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0430"},
gug(){return"\u0412\u043e \u0432\u0445\u043e\u0434\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 \u043d\u0435\u0442 \u0438\u0441\u0442\u043e\u0440\u0438\u0438 \u043f\u0440\u0430\u0432\u043e\u043a \u2014 \u0432\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0439 \u0442\u0435\u043a\u0441\u0442, PDF \u0438\u043b\u0438 \u0444\u0430\u0439\u043b \u0441 \u043e\u0447\u0438\u0449\u0435\u043d\u043d\u043e\u0439 \u0437\u0430\u043f\u0438\u0441\u044c\u044e. \u0421\u0443\u0434\u0438\u0442\u044c \u043e \u043f\u0440\u043e\u0438\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0438 \u0437\u0434\u0435\u0441\u044c \u043d\u0435 \u043f\u043e \u0447\u0435\u043c\u0443, \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0430\u043d\u0430\u043b\u0438\u0437 \u0442\u0435\u043a\u0441\u0442\u0430."},
ue(a){return"\u0412\u0440\u0435\u043c\u044f \u043f\u0440\u0430\u0432\u043a\u0438, \u0437\u0430\u043f\u0438\u0441\u0430\u043d\u043d\u043e\u0435 \u0432 \u0444\u0430\u0439\u043b\u0435: "+a+" \u043c\u0438\u043d"},
uh(a){return"\u0427\u0438\u0441\u043b\u043e \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0439: "+a},
