uq(a,b){return"\u0412 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u043c \u0442\u0435\u043a\u0441\u0442\u0435 \u0432\u0441\u0435\u0433\u043e "+a+" \u043c\u0435\u0442\u043a(\u0430/\u0438) \u0441\u0435\u0430\u043d\u0441\u0430 \u043f\u0440\u0430\u0432\u043a\u0438 \u043d\u0430 "+b+" \u0441\u043b\u043e\u0432. \u041f\u0440\u0438 \u043e\u0431\u044b\u0447\u043d\u043e\u043c \u043f\u0438\u0441\u044c\u043c\u0435 \u0438\u0445 \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u0434\u0435\u0441\u044f\u0442\u043a\u0438; \u0442\u0430\u043a\u0430\u044f \u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0446\u0438\u044f \u043e\u0431\u044b\u0447\u043d\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u0442\u0435\u043a\u0441\u0442 \u043f\u043e\u043f\u0430\u043b \u0446\u0435\u043b\u0438\u043a\u043e\u043c \u0437\u0430 \u043e\u0434\u0438\u043d \u0440\u0430\u0437 \u2014 \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0432\u0441\u0442\u0430\u0432\u043a\u043e\u0439."},
ur(a,b,c){return""+a+" \u0441\u043b\u043e\u0432 \u043f\u0440\u0438 "+b+" \u043c\u0438\u043d \u0437\u0430\u043f\u0438\u0441\u0430\u043d\u043d\u043e\u0439 \u043f\u0440\u0430\u0432\u043a\u0438 \u2014 \u044d\u0442\u043e "+c+" \u0441\u043b\u043e\u0432 \u0432 \u043c\u0438\u043d\u0443\u0442\u0443, \u043d\u0430\u043c\u043d\u043e\u0433\u043e \u0432\u044b\u0448\u0435 \u0442\u043e\u0433\u043e, \u0447\u0442\u043e \u0443\u0434\u0430\u0451\u0442\u0441\u044f \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0442\u044c \u043f\u0440\u0438 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u043c \u043f\u0438\u0441\u044c\u043c\u0435."},
uo(a){return"\u0424\u0430\u0439\u043b \u043f\u043e\u0447\u0442\u0438 \u043d\u0435 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442 \u0432\u0440\u0435\u043c\u044f \u043f\u0440\u0430\u0432\u043a\u0438, \u0445\u043e\u0442\u044f \u0432 \u0442\u0435\u043a\u0441\u0442\u0435 "+a+" \u0441\u043b\u043e\u0432."},
un(a,b){return""+b+" \u0441\u043b\u043e\u0432 \u0442\u0435\u043a\u0441\u0442\u0430 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u043b\u0438\u0441\u044c \u0432\u0441\u0435\u0433\u043e "+a+" \u0440\u0430\u0437."},
gud(){return"\u0412\u0430\u0436\u043d\u043e: \u044d\u0442\u0438 \u0437\u0430\u043f\u0438\u0441\u0438 \u043c\u043e\u0436\u043d\u043e \u0441\u0442\u0435\u0440\u0435\u0442\u044c \u0438\u043b\u0438 \u043e\u0431\u043d\u0443\u043b\u0438\u0442\u044c \u2014 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435 \u043f\u043e\u0434 \u043d\u043e\u0432\u044b\u043c \u0438\u043c\u0435\u043d\u0435\u043c, \u043e\u043d\u043b\u0430\u0439\u043d-\u043a\u043e\u043d\u0432\u0435\u0440\u0442\u0430\u0446\u0438\u044f, \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0438\u0437 Google \u0414\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u043e\u0432 \u0438\u043b\u0438 \u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0432 \u043d\u043e\u0432\u044b\u0439 \u0444\u0430\u0439\u043b \u0441\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u044e\u0442 \u0438\u0445. \u041f\u043e\u044d\u0442\u043e\u043c\u0443 \u0441\u0438\u0433\u043d\u0430\u043b \u0437\u0434\u0435\u0441\u044c \u2014 \u0432\u0441\u043f\u043e\u043c\u043e\u0433\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u0441\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e, \u0430 \u043d\u0435 \u0441\u0430\u043c\u043e\u0441\u0442\u043e\u044f\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0432\u044b\u0432\u043e\u0434; \u0435\u0433\u043e \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u0442\u043e\u0436\u0435 \u043d\u0435 \u0434\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u0447\u0442\u043e \u043f\u0438\u0441\u0430\u043b \u0447\u0435\u043b\u043e\u0432\u0435\u043a."},
